from abc import ABC, abstractmethod


class Item(ABC):
    """Contrato: todo item da biblioteca informa o prazo de empréstimo."""

    def __init__(self, titulo, ano):
        self.titulo = titulo
        self.ano = ano

    @abstractmethod
    def prazo_dias(self):
        pass

    def descricao(self):
        return f"{self.titulo} ({self.ano}) - prazo {self.prazo_dias()} dias"


class Livro(Item):
    def __init__(self, titulo, ano, autor):
        super().__init__(titulo, ano)
        self.autor = autor

    def prazo_dias(self):
        return 14

    def descricao(self):
        return f"{super().descricao()} - {self.autor}"


class Revista(Item):
    def prazo_dias(self):
        return 7


class Leitor:
    def __init__(self, nome):
        self.nome = nome
        self.__emprestimos = []

    @property
    def emprestimos(self):
        return list(self.__emprestimos)   # devolve uma cópia

    def pegar(self, item, limite=3):
        if len(self.__emprestimos) >= limite:
            print(f"{self.nome} já está no limite de {limite} itens.")
            return False
        self.__emprestimos.append(item)
        return True


class Biblioteca:
    def __init__(self):
        self.acervo = []   # agregação: os itens são criados fora

    def cadastrar(self, item):
        self.acervo.append(item)

    def ordenar_por_ano(self):
        return sorted(self.acervo, key=lambda i: i.ano)


bib = Biblioteca()
bib.cadastrar(Livro("Dom Casmurro", 1899, "Machado de Assis"))
bib.cadastrar(Revista("Ciência Hoje", 2024))
bib.cadastrar(Livro("O Cortiço", 1890, "Aluísio Azevedo"))

for item in bib.ordenar_por_ano():
    print(item.descricao())

ana = Leitor("Ana")
ana.pegar(bib.acervo[0])
print(f"{ana.nome} está com {len(ana.emprestimos)} item(ns).")

