class ContaBancaria:
    def __init__(self, titular):
        self.titular = titular
        self.__saldo = 0

    @property
    def saldo(self):
        return self.__saldo

    def depositar(self, valor):
        if valor > 0:
            self.__saldo += valor
        else:
            print("Depósito inválido.")

    def sacar(self, valor):
        if 0 < valor <= self.__saldo:
            self.__saldo -= valor
        else:
            print("Saque inválido.")

c = ContaBancaria("Ana")
c.depositar(100)
c.sacar(150)      # Saque inválido.
print(c.saldo)    # 100

def aplicar(lista, operacao):
    return [operacao(item) for item in lista]

def eh_par(n):
    return n % 2 == 0

print(aplicar([1, 2, 3], lambda n: n * 3))   # [3, 6, 9]
print(aplicar([1, 2, 3], eh_par))            # [False, True, False]

