class ItemPedido:
    def __init__(self, produto, preco, qtd):
        self.produto = produto
        self.preco = preco
        self.qtd = qtd

    def subtotal(self):
        return self.preco * self.qtd

class Pedido:
    def __init__(self):
        self.itens = []

    def adicionar_item(self, produto, preco, qtd=1):
        self.itens.append(ItemPedido(produto, preco, qtd))   # o Pedido cria o item

    def total(self):
        return sum(item.subtotal() for item in self.itens)

p = Pedido()
p.adicionar_item("Caderno", 18.0, 2)
p.adicionar_item("Caneta", 2.5, 4)
print(p.total())   # 46.0

from abc import ABC, abstractmethod
import math

class Forma(ABC):
    @abstractmethod
    def area(self):
        pass

class Retangulo(Forma):
    def __init__(self, largura, altura):
        self.largura = largura
        self.altura = altura

    def area(self):
        return self.largura * self.altura

class Circulo(Forma):
    def __init__(self, raio):
        self.raio = raio

    def area(self):
        return math.pi * self.raio ** 2

formas = [Retangulo(2, 3), Circulo(1)]
print(f"{sum(f.area() for f in formas):.2f}")   # 9.14
